def rank_with_length_penalty(candidates, alpha=0.7):
    scored = {}
    for label, (log_prob, length) in candidates.items():
        penalty = (5.0 + length) ** alpha / (6.0 ** alpha)
        scored[label] = log_prob / penalty
    ranked = sorted(scored.items(), key=lambda x: x[1], reverse=True)
    return ranked
